SELECT IMPDEC_NO ,ACPT_DATE ,SUM(QY) AS QY ,SUM(REMNDR_QY) AS REMNDR_QY ,ROUND(SUM(CVODV_KRW)) AS CVODV_KRW ,ROUND(SUM(CVODV_USD)) AS CVODV_USD ,ROUND(SUM(TOT_TAXAMT)) AS TOT_TAXAMT ,FLOOR(SUM((CASE WHEN NVL(REMNDR_QY, 0) = 0 THEN 0 ELSE CASE WHEN REMNDR_QY = QY THEN (NVL(CSTMS, 0) + NVL(INTTAX, 0) + NVL(ECX_AMOUNT, 0) + NVL(AGSPT, 0) + NVL(TRANTAX, 0) + NVL(LQTX_AMOUNT, 0)) ELSE (NVL(CSTMS, 0) + NVL(INTTAX, 0) + NVL(ECX_AMOUNT, 0) + NVL(AGSPT, 0) + NVL(TRANTAX, 0) + NVL(LQTX_AMOUNT, 0)) / NVL(QY, 0) * NVL(REMNDR_QY, 0) END END))) AS REMNDR_TAX ,MAX(CASE WHEN REMNDR_QY IS NULL OR REMNDR_QY = QY THEN '미사용' WHEN REMNDR_QY = 0 THEN '모두사용' ELSE '일부' END) AS USE_YN ,MAX(LAST_USE_YYYYMMDD) AS LAST_USE_YYYYMMDD ,IMPDEC_MANAGE_NO ,TRUNC(SUM(DLIVY_QY), 2) AS DLIVY_QY ,FLOOR(SUM((CASE WHEN NVL(DLIVY_QY, 0) = 0 THEN 0 ELSE (NVL(CSTMS, 0) + NVL(INTTAX, 0) + NVL(ECX_AMOUNT, 0) + NVL(AGSPT, 0) + NVL(TRANTAX, 0) + NVL(LQTX_AMOUNT, 0)) / QY * NVL(DLIVY_QY, 0) END))) AS USE_TAX FROM (SELECT A.IMPDEC_NO ,A.ACPT_DATE ,B.LNE_NO ,B.POUCH_NO ,B.QY ,B.CSTMS ,B.INTTAX ,B.ECX_AMOUNT ,B.AGSPT ,B.TRANTAX ,B.LQTX_AMOUNT , NVL((CASE WHEN C.IMP_BASS_UNIT = C.BASS_UNIT THEN C.REMNDR_QY ELSE (CASE WHEN C.IMP_BASS_UNIT = 'KG' THEN TRUNC(C.REMNDR_QY / 1000 ,2) WHEN C.IMP_BASS_UNIT = 'LB' THEN TRUNC(C.REMNDR_QY / 0.453592 / 1000,2) WHEN C.IMP_BASS_UNIT = 'DR' THEN TRUNC(C.REMNDR_QY / 1000 / 30,2) WHEN C.IMP_BASS_UNIT = 'GR' THEN TRUNC(C.REMNDR_QY / 0.064799,2) WHEN C.IMP_BASS_UNIT = 'MT' THEN TRUNC(C.REMNDR_QY / 1000 / 1000,2) ELSE B.QY END) END), B.QY) AS REMNDR_QY
, NVL((CASE WHEN C.IMP_BASS_UNIT = C.BASS_UNIT THEN C.DLIVY_QY ELSE (CASE WHEN C.IMP_BASS_UNIT = 'KG' THEN TRUNC(C.DLIVY_QY / 1000,2) WHEN C.IMP_BASS_UNIT = 'LB' THEN TRUNC(C.DLIVY_QY / 0.453592 / 1000,2) WHEN C.IMP_BASS_UNIT = 'DR' THEN TRUNC(C.DLIVY_QY / 1000 / 30,2) WHEN C.IMP_BASS_UNIT = 'GR' THEN TRUNC(C.DLIVY_QY / 0.064799,2) WHEN C.IMP_BASS_UNIT = 'MT' THEN TRUNC(C.DLIVY_QY / 1000 / 1000,2) ELSE 0 END) END), 0) AS DLIVY_QY ,NVL(A.CVODV_KRW, 0) AS CVODV_KRW ,NVL(A.CVODV_USD, 0) AS CVODV_USD
,NVL(B.CSTMS, 0) + NVL(B.INTTAX, 0) + NVL(B.ECX_AMOUNT, 0) + NVL(B.AGSPT, 0) + NVL(B.TRANTAX, 0) + NVL(B.LQTX_AMOUNT, 0) AS TOT_TAXAMT ,C.LAST_USE_YYYYMMDD ,A.IMPDEC_MANAGE_NO FROM IMPDEC_CERFIN_HDER A INNER JOIN IMPDEC_CERFIN_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO LEFT OUTER JOIN INCME_LOCAL_BNT_SM C ON A.COMPANY_CODE = C.COMPANY_CODE AND A.DIVISION_CODE = C.DIVISION_CODE AND A.IMPDEC_NO = C.IMPDEC_NO AND B.LNE_NO = C.LNE_NO AND B.POUCH_NO = C.POUCH_NO AND B.ITEM_CODE = C.ITEM_CODE AND B.COMPANY_CODE = C.COMPANY_CODE AND B.DIVISION_CODE = C.DIVISION_CODE WHERE 1=1 AND A.COMPANY_CODE = #{COMPANY_CODE}
AND A.ACPT_DATE >= REPLACE(#{CAL_SEARCH_FROM_DATE}, '-', '')
AND A.ACPT_DATE <= REPLACE(#{CAL_SEARCH_TO_DATE}, '-', '')
AND B.HS_CODE LIKE #{HS_CODE}||'%'
AND A.INCME_DELNG_SE = #{INCME_DELNG_SE}
AND A.INCME_TYPE = #{INCME_TYPE}
AND B.BL_NO LIKE #{BL_NO}||'%'
AND B.LC_NO LIKE #{LC_NO}||'%'
AND A.IMPDEC_NO = #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE = #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_NM = #{SEARCH_KEY_WORD}
AND B.ITEM_NM LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_NM LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
) GROUP BY IMPDEC_NO,ACPT_DATE,IMPDEC_MANAGE_NO

SELECT T.COMPANY_CODE ,T.DIVISION_CODE ,T.EXPDECL_MANAGE_NO ,T.XPORT_STTEMNT_NO ,T.MANUFAC_NAME ,T.EXPORTER_NAME ,T.ONBOARD_DATE ,T.NATION_CODE ,T.INV_NO ,SUM(T.ITEM_QTY) AS ITEM_QTY FROM EXPORT_CERT_MST T WHERE T.COMPANY_CODE = #{COMPANY_CODE} AND T.HS_CODE IS NOT NULL AND T.EXPDECL_MANAGE_NO = #{EXPDECL_MANAGE_NO}
AND T.INV_NO = #{INV_NO}
GROUP BY T.COMPANY_CODE ,T.DIVISION_CODE ,T.EXPDECL_MANAGE_NO ,T.XPORT_STTEMNT_NO ,T.MANUFAC_NAME ,T.EXPORTER_NAME ,T.ONBOARD_DATE ,T.NATION_CODE ,T.INV_NO

SELECT DRM.COMPANY_CODE, DRM.STDR_MT, DRM.DIVISION_CODE, DRM.ITEM_CODE, DRM.INPT_DIVISION_CODE, DRM.BOM_PRDLST, DRM.BYPRD_ATRB_GROUP, DRM.WRHOUSNG_QY, DRM.ACPLC_CRNCY_AMOUNT, DRM.UNIT_BYPRD_AMOUNT, DRM.DDC_RATE_PRDCTN, DRM.BASS_UNIT, DRM.QY, DRM.ACPLC_CRNCY, DRM.INDVDLZ_INPT_AMOUNT FROM DDC_RATE_MANAGE DRM WHERE DRM.COMPANY_CODE = #{COMPANY_CODE}
AND DRM.STDR_MT >= REPLACE(#{CAL_SEARCH_FROM_DATE}, '-', '')
AND DRM.STDR_MT <= REPLACE(#{CAL_SEARCH_TO_DATE}, '-', '')
AND DRM.ITEM_CODE = #{SEARCH_KEY_WORD}
AND DRM.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND DRM.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT PDR.COMPANY_CODE, PDR.DIVISION_CODE, PDR.ITEM_CODE, PDR.ITEM_NAME, PDR.PRDCTN_DATE, PDR.CMPLT_DATE, PDR.SHIPMNT_DATE, PDR.HKMC_SE, PDR.PROD_DIVISION_CODE FROM PRDCTN_DATE_TRACE PDR WHERE PDR.COMPANY_CODE = #{COMPANY_CODE}
AND PDR.PRDCTN_DATE >= REPLACE(#{CAL_SEARCH_FROM_DATE}, '-', '')
AND PDR.PRDCTN_DATE <= REPLACE(#{CAL_SEARCH_TO_DATE}, '-', '')
AND PDR.ITEM_CODE = #{SEARCH_KEY_WORD}
AND PDR.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND PDR.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT ILBS.EFECT_BGNDE, ILBS.IMPDEC_NO, ILBS.LNE_NO, ILBS.POUCH_NO, ILBS.ITEM_CODE, ILBS.HS_CODE, ILBS.COMPANY_CODE, ILBS.STDR_MT, ILBS.ACPT_DATE, ILBS.TRNSFR_DATE, ILBS.QY, ILBS.BASS_UNIT, ILBS.INCME_TARRATE, ILBS.CSTMS, ILBS.CSTMS_AMOUNT, ILBS.CSTMS_AMOUNT_UNIT, ILBS.AMOUNT_CRNCY, ILBS.DLIVY_QY, ILBS.REMNDR_QY, ILBS.RAWMTRL_SE, ILBS.BKRECKN_MT, ILBS.VENDOR_CODE FROM INCME_LOCAL_BNT_SM ILBS WHERE ILBS.COMPANY_CODE = #{COMPANY_CODE}
AND ILBS.STDR_MT >= REPLACE(#{CAL_SEARCH_FROM_DATE}, '-', '')
AND ILBS.STDR_MT <= REPLACE(#{CAL_SEARCH_TO_DATE}, '-', '')
AND ILBS.ITEM_CODE = #{SEARCH_KEY_WORD}
AND ILBS.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND ILBS.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT FIV.COMPANY_CODE, FIV.YEAR, FIV.EFECT_BGNDE, FIV.EFECT_ENDDE, FIV.ITEM_CODE, FIV.INCME_TARRATE, FIV.HS_CODE, FIV.ITEM_NM, FIV.QY, FIV.BASS_UNIT, FIV.PURCHS_RATE FROM FYER_INCME_VOLM FIV WHERE FIV.COMPANY_CODE = #{COMPANY_CODE}
AND FIV.YEAR = #{CAL_SEARCH_YYYY}
AND FIV.ITEM_CODE = #{SEARCH_KEY_WORD}
AND FIV.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND FIV.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT PL.COMPANY_CODE , PL.DIVISION_CODE , PL.WAREHOUSING_NO , PL.SEQ , PL.WAREHOUSING_YEAR , PL.WAREHOUSING_DATE , CASE WHEN PL.WAREHOUSING_TYPE = 'IMP' THEN '수입' ELSE '내수' END AS WAREHOUSING_TYPE , PL.ORDER_NO , PL.ORDER_SEQ , PL.VENDOR_CODE , PL.MAKER_NAME , PL.ITEM_CODE , PL.ITEM_NAME , PL.LAN , PL.POUCH , PL.PERMIT_DATE , PL.CLEARLANCE_NO , PL.CSTMS , PL.CSTMS_RATE , PL.ORIGIN_NATION , PL.AMOUNT_FOREIGN , PL.UNIT_PRICE_FOREIGN , PL.EXCHANGE_DATE , PL.EXCHANGE_RATE , PL.BL_NO , PL.BL_QUANTITY , PL.WAREHOUSING_QTY , PL.WAREHOUSING_AMOUNT , PL.CURRENCY , PL.ASSETS_TYPE , PL.UNIT , PL.UNIT_PRICE , TO_CHAR(PL.CREATE_DATE, 'YYYY-MM-DD') AS CREATE_DATE , TO_CHAR(PL.UPDATE_DATE, 'YYYY-MM-DD') AS UPDATE_DATE FROM PO_LEDGER PL WHERE 1=1 AND PL.COMPANY_CODE = #{COMPANY_CODE}
AND PL.WAREHOUSING_DATE LIKE REPLACE(#{WAREHOUSING_DATE}, '-', '') || '%'
AND PL.VENDOR_CODE = #{SEARCH_KEY_WORD}
AND PL.VENDOR_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND PL.VENDOR_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND PL.ITEM_CODE = #{SEARCH_KEY_WORD}
AND PL.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND PL.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT A.SALES_NO, B.SALES_SEQ, A.EXPORT_FLAG, CASE WHEN A.EXPORT_FLAG = 'D' THEN '내수' ELSE '수출' END AS EXPORT_FLAG_NAME, A.CUSTOMER_CODE, A.INVOICE_DATE, B.PRODUCT_CODE, B.PRODUCT_UNIT, B.AMOUNT, B.AMOUNT_FOREIGN, B.CURRENCY, B.PRODUCT_ASSETS_TYPE, A.ARRIVAL_NATION, A.ARRIVAL_PORT_NAME, A.BL_NO, A.DELIVERY_CUSTOMER_CODE, A.INCOTERMS, A.INVOICE_NO, A.PACKING_COUNT, A.PACKING_MARK, A.SHIPPING_DATE, A.VEHICLE_NAME, C.CUSTOMER_NAME, I.ITEM_NAME, A.PAY_NO, A.SALES_DOC_NO, A.TAX_INVOICE_NO, A.TAX_INVOICE_DATE FROM SALES_MST A INNER JOIN SALES_DTL B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.SALES_NO = B.SALES_NO LEFT OUTER JOIN CUSTOMER C ON A.COMPANY_CODE = C.COMPANY_CODE AND A.CUSTOMER_CODE = C.CUSTOMER_CODE LEFT OUTER JOIN ITEM_MST I ON B.COMPANY_CODE = I.COMPANY_CODE AND B.PRODUCT_CODE = I.ITEM_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND A.INVOICE_DATE LIKE REPLACE(#{PRIC_RQEST_DATE}, '-', '') || '%'
AND A.EXPORT_FLAG = (CASE WHEN 'DOM' = #{SEARCH_EXPORT_FLAG} THEN 'D' ELSE 'E' END)
AND C.CUSTOMER_NAME LIKE #{SEARCH_CUSTOMER_TEXT}||'%'
AND A.CUSTOMER_CODE = #{SEARCH_CUSTOMER_TEXT}
AND B.PRODUCT_CODE = #{SEARCH_KEY_WORD}
AND B.PRODUCT_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.PRODUCT_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND I.ITEM_NAME = #{SEARCH_KEY_WORD}
AND I.ITEM_NAME LIKE #{SEARCH_KEY_WORD}|| '%'
AND I.ITEM_NAME LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT A.COMPANY_CODE, A.YYYYMM, A.DIVISION_CODE, A.ITEM_CODE, A.ITEM_NAME, A.BR_GROUP, A.BR_CODE, A.ASSETS_TYPE, A.P_CLASS, A.F_CENTER, A.CURRENCY, A.UNIT, A.INITIAL_QTY, A.INITIAL_AMOUNT, A.INITIAL_PRICE, A.INPUT_QTY, A.INPUT_AMOUNT, A.INPUT_PRICE, A.PROD_INPUT_QTY, A.PROD_INPUT_AMOUNT, A.PROD_INPUT_PRICE, A.TRANS_INPUT_QTY, A.TRANS_INPUT_AMOUNT, A.TRANS_INPUT_PRICE, A.SALES_RETURN_QTY, A.SALES_RETURN_AMOUNT, A.SALES_RETURN_PRICE, A.OTHER_RETURN_QTY, A.OTHER_RETURN_AMOUNT, A.OTHER_RETURN_PRICE, A.ETC_INPUT_QTY, A.ETC_INPUT_AMOUNT, A.ETC_INPUT_PRICE, A.SALES_ISSUE_QTY, A.SALES_ISSUE_AMOUNT, A.SALES_ISSUE_PRICE, A.OTHER_ISSUE_QTY, A.OTHER_ISSUE_AMOUNT, A.OTHER_ISSUE_PRICE, A.PROD_ISSUE_QTY, A.PROD_ISSUE_AMOUNT, A.PROD_ISSUE_PRICE, A.STOCK_ISSUE_QTY, A.STOCK_ISSUE_AMOUNT, A.STOCK_ISSUE_PRICE, A.ETC_ISSUE_QTY, A.ETC_ISSUE_AMOUNT, A.ETC_ISSUE_PRICE, A.COST_DISC, A.MATERIAL_ADJ, A.INVENTORY_QTY, A.INVENTORY_AMOUNT, A.INVENTORY_PRICE FROM MATERIAL_INV_BAL A WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND A.YYYYMM LIKE REPLACE(#{STDR_MT}, '-', '') || '%'
AND A.ITEM_CODE = #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT COMPANY_CODE, START_DATE, END_DATE, HS_CODE10, HS_DESC, PRICE FROM LF_REFUND_MST LRM WHERE LRM.COMPANY_CODE = #{COMPANY_CODE} AND #{APPLY_DATE} BETWEEN LRM.START_DATE AND LRM.END_DATE
AND LRM.HS_CODE10 = #{HS_CODE10}
AND LRM.PRICE = #{SEARCH_KEY_WORD}
AND LRM.PRICE LIKE #{SEARCH_KEY_WORD}|| '%'
AND LRM.PRICE LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'
AND LRM.HS_DESC = #{SEARCH_KEY_WORD}
AND LRM.HS_DESC LIKE #{SEARCH_KEY_WORD}|| '%'
AND LRM.HS_DESC LIKE '%'|| #{SEARCH_KEY_WORD}|| '%'

SELECT SH.APPLY_YEAR, SH.HS_SEQ, SH.HSCODE10, SH.HS_DESC, SH.REMARK, SH.PRE_HS_SEQ, SH.PRE_HSCODE10 FROM SHORTEN_HSCODE SH WHERE SH.COMPANY_CODE = #{COMPANY_CODE} AND SH.APPLY_YEAR = #{APPLY_YEAR}
AND SH.HSCODE10 BETWEEN #{FROM_HSCODE10} AND #{TO_HSCODE10}
