SELECT '공급업체' AS DATA_TYPE, V.VENDOR_CODE AS VC_CODE, V.NATION_CODE AS VC_NATION, V.VENDOR_NAME AS VC_NAME, V.VENDOR_NAME_ENG AS VC_ENG_NAME, V.BUSINESS_NO, V.OFFICER_NAME, V.OFFICER_NAME_ENG, V.ADDRESS, V.ADDRESS_ENG, V.FAX_NO, V.TEL_NO, V.CUSTOM_UNQ_CODE, V.DELETE_YN FROM VENDOR V WHERE COMPANY_CODE = #{COMPANY_CODE}
AND V.VENDOR_NAME LIKE #{VENDOR_NAME}||'%'
AND V.BIZRNO = #{BIZRNO}

SELECT '고객사' AS DATA_TYPE ,C.CUSTOMER_CODE AS VC_CODE ,C.NATION_CODE AS VC_NATION ,C.CUSTOMER_NAME AS VC_NAME ,C.CUSTOMER_NAME_ENG AS VC_ENG_NAME ,C.BUSINESS_NO ,C.OFFICER_NAME ,C.OFFICER_NAME_ENG ,C.ADDRESS ,C.ADDRESS_ENG ,C.FAX_NO ,C.TEL_NO ,ECTMRK AS CUSTOM_UNQ_CODE ,C.DELETE_YN FROM CUSTOMER C WHERE C.COMPANY_CODE = '1100'
AND C.CUSTOMER_NAME LIKE #{VENDOR_NAME}||'%'
AND C.BUSINESS_NO = #{BIZRNO}

