AND V.BUSINESS_NO = #{BIZRNO}
UNION ALL SELECT '고객사' AS DATA_TYPE ,C.CUSTOMER_CODE AS VC_CODE ,C.NATION_CODE AS VC_NATION ,C.CUSTOMER_NAME AS VC_NAME ,C.CUSTOMER_NAME_ENG AS VC_ENG_NAME ,C.BUSINESS_NO ,C.OFFICER_NAME ,C.OFFICER_NAME_ENG ,C.ADDRESS ,C.ADDRESS_ENG ,C.FAX_NO ,C.TEL_NO ,ECTMRK AS CUSTOM_UNQ_CODE ,C.DELETE_YN FROM CUSTOMER C WHERE C.COMPANY_CODE = '1100'
AND C.CUSTOMER_NAME LIKE #{VENDOR_NAME}||'%'
AND C.BUSINESS_NO = #{BIZRNO}

