SELECT A.COMPANY_CODE, A.DIVISION_CODE, A.SALES_LEDGER_NO, A.SALES_LEDGER_YEAR, A.SALES_LEDGER_SEQ, A.SALES_DATE, A.ITEM_MOVE_TYPE, A.ASSETS_TYPE, A.ITEM_CODE, A.ITEM_NAME, A.HS_CODE, A.CUSTOMER_CODE, A.QUANTITY, A.UNIT, A.AMOUNT FROM SALES_LEDGER A WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.DIVISION_CODE = #{DIVISION_CODE} AND A.SALES_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
